// A mismatch remains the same refusal. These bounded copies are historical
// diagnostics only; they cannot admit a schema or authorize any import effect.
type ownedAnnotationSchemaMismatchError struct {
	cause      error
	diagnostic []byte
}

func (e *ownedAnnotationSchemaMismatchError) Error() string { return e.cause.Error() }
func (e *ownedAnnotationSchemaMismatchError) Unwrap() error { return e.cause }
func (e *ownedAnnotationSchemaMismatchError) OwnedAnnotationSchemaDiagnostic() []byte {
	return append([]byte(nil), e.diagnostic...)
}

func ownedAnnotationSchemaMismatch(plan *ownedAnnotationMemberPlan, source, target *pb.SnapshotWithType) error {
	cause := ownedAnnotationRefused("source_target_schema_semantics_differ")
	const snapshotLimit = 256 << 10
	const jsonLimit = 1 << 20
	record := map[string]any{
		"schema": 1, "schema_key": plan.nativeKey.Marshal(),
		"source_object_id": plan.sourceID, "target_object_id": plan.expectedTarget,
		"refusal": cause.Error(), "comparator_result": false,
		"snapshot_limit_bytes": snapshotLimit, "json_view_limit_bytes": jsonLimit,
		"normalized_at_actual_failed_comparison": true, "import_accepted": false,
	}
	for _, side := range []struct {
		name  string
		value *pb.SnapshotWithType
	}{{"source", source}, {"target", target}} {
		prefix := "normalized_" + side.name + "_"
		size := proto.Size(side.value)
		record[prefix+"declared_bytes"] = size
		record[prefix+"truncated"] = false
		if size < 0 || size > snapshotLimit {
			record[prefix+"status"] = "OMITTED_SIZE_LIMIT"
			continue
		}
		raw, err := proto.Marshal(side.value)
		record[prefix+"actual_bytes"] = len(raw)
		if err != nil {
			record[prefix+"status"] = "OMITTED_MARSHAL_FAILURE"
			continue
		}
		if len(raw) != size || len(raw) > snapshotLimit {
			record[prefix+"status"] = "OMITTED_SIZE_MISMATCH"
			continue
		}
		record[prefix+"protobuf"] = raw
		record[prefix+"status"] = "COMPLETE"
		// The protobuf bytes above retain every field; this JSON view only
		// makes the same copied message convenient to inspect.
		view, viewErr := json.Marshal(side.value)
		record[prefix+"json_view_bytes"] = len(view)
		if viewErr != nil {
			record[prefix+"json_view_status"] = "OMITTED_MARSHAL_FAILURE"
		} else if len(view) > jsonLimit {
			record[prefix+"json_view_status"] = "OMITTED_SIZE_LIMIT"
		} else {
			record[prefix+"json_view"] = json.RawMessage(view)
			record[prefix+"json_view_status"] = "COMPLETE"
		}
	}
	raw, err := json.Marshal(record)
	if err != nil || len(raw) > 3<<20 {
		// Diagnostics must never replace or suppress the original refusal.
		return cause
	}
	return &ownedAnnotationSchemaMismatchError{cause: cause, diagnostic: raw}
}

